public class DiscountTestDataFactory extends TestDataFactory {
    protected override SObject prepare() {
        return new Discount__c(
                Name = 'Test Discount',
                Is_Active__c = true,
                Discount_Type__c = ConstUtil.DISCOUNT_TYPE_TIME_BOUND,
                Value_Type__c = ConstUtil.DISCOUNT_VALUE_TYPE_PERCENTAGE,
                Discount_Value__c = 10.0,
                Start_Date__c = Date.today(),
                End_Date__c = Date.today().addDays(30)
        );
    }

    public override SObject create() {
        Discount__c discount = (Discount__c) prepare();
        insert discount;
        return discount;
    }

    private class ConditionalDiscountFactory extends DiscountTestDataFactory {
        public override SObject create() {
            Discount__c discount = (Discount__c) prepare();
            discount.Discount_Type__c = ConstUtil.DISCOUNT_TYPE_CONDITIONAL;
            discount.Condition_Logic_Field__c = 'Order.Products_Amount';
            discount.Condition_Logic_Operator__c = '>';
            discount.Condition_Logic_Numeric_Value__c = 1;
            insert discount;
            return discount;
        }
    }

    private class RecurringDiscountFactory extends DiscountTestDataFactory {
        public override SObject create() {
            Discount__c discount = (Discount__c) prepare();
            discount.Discount_Type__c = ConstUtil.DISCOUNT_TYPE_RECURRING;
            discount.Recurring_Date_Start__c = Datetime.now();
            discount.Recurring_Date_End__c = Datetime.now().addHours(2);
            discount.Recurring_Date_Repeat_By__c = ConstUtil.DISCOUNT_RECURRING_DATE_REPEAT_BY_DAILY;
            insert discount;
            return discount;
        }
    }

    private class InactiveDiscountFactory extends DiscountTestDataFactory {
        public override SObject create() {
            Discount__c discount = (Discount__c) prepare();
            discount.Is_Active__c = false;
            insert discount;
            return discount;
        }
    }

    public static DiscountTestDataFactory conditional() {
        return new ConditionalDiscountFactory();
    }

    public static DiscountTestDataFactory recurring() {
        return new RecurringDiscountFactory();
    }

    public static DiscountTestDataFactory inactive() {
        return new InactiveDiscountFactory();
    }
}

